mapper.select:
SELECT *
FROM blog_file


        uploader_id = #{uploader}


        AND uploader_id = #{filterUploader}


        AND (
            INSTR(original_name, #{query.keyword}) > 0
            OR INSTR(
                CONVERT(SUBSTRING_INDEX(object_key, '/', -1) USING utf8mb4) COLLATE utf8mb4_bin,
                #{query.keyword}
            ) > 0
        )


        AND mime_type = #{query.mimeType}


ORDER BY create_time DESC, file_id DESC

mapper.delete:
DELETE FROM blog_file
WHERE file_id = #{id}

    AND uploader_id = #{uploader}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM blog_article_file
    WHERE file_id = #{fileId}
)

SELECT EXISTS (
    SELECT 1
    FROM blog_article_file
    WHERE article_id = #{articleId}
      AND file_id = #{fileId}
)
